const mealID = localStorage.getItem("meal");
const category = localStorage.getItem("category");

const table = document.getElementById("ingredientTable");
const mealTitle = document.getElementById("mealTitle");

const feelFree = document.getElementById("feelFree");
const rates = document.getElementById("rates");

if (category && mealID) {
  const meal = foodData[category].meals.find((m) => m.id === mealID);
  if (meal) {
    mealTitle.textContent = meal.name;
    meal.ingredients.forEach((item) => {
      table.innerHTML += `
                <tr>
                    <td>
                        <input class="product" value="${item.product}">
                    </td>
                    <td>
                        <input type="number" min="0" class="qty" value="${item.quantity}">
                    </td>
                    <td>
                        <input class="unit" value="${item.unit}" list="unitOptions" placeholder="bv. kg">
                    </td>
                    <td>
                        <input class="weight" value="${item.weight || 1}">
                    </td>
                    <td class="totalWeight">
                        0
                    </td>
                    <td>
                        <input type="number" min="0" class="price" value="${item.price}">
                    </td>
                    <td class="rowTotal">0</td>
                    <td class="remove-cell">
                        <button class="remove-btn">✖</button> 
                    </td> 
                </tr>
            `;
    });
  }
} else {
  mealTitle.textContent = "Pasgemaakte Produk-sakrekenaar";
  rates.textContent = "";
  feelFree.textContent =
    "Voeg jou eie produkte hieronder by en vul die besonderhede in om jou aanvangskapitaal te bereken.";
}

calculate();

document.getElementById("calculate").onclick = calculate;

function calculate() {
  let total = 0;
  document.querySelectorAll("tbody tr").forEach((row) => {
    const qty = parseFloat(row.querySelector(".qty").value) || 0;
    const price = parseFloat(row.querySelector(".price").value) || 0;
    const weight = parseFloat(row.querySelector(".weight")?.value) || 0;
    const unit = row.querySelector(".unit")?.value || "";

    // Total Wt./Vol. stays purely informational — how much of this
    // ingredient you'll have in total, for your own reference.
    const totalWeight = qty * weight;
    row.querySelector(".totalWeight").textContent = `${totalWeight} ${unit}`;

    // Price is simply what you're paying for this line: quantity × price.
    // No unit conversion — "price" always means "cost for this quantity."
    const rowTotal = qty * price;
    row.querySelector(".rowTotal").textContent = "R" + rowTotal.toFixed(2);
    total += rowTotal;
  });
  document.getElementById("capital").textContent = "R" + total.toFixed(2);
}

document.getElementById("addProduct").onclick = () => {
  table.innerHTML += `
        <tr>
            <td><input class="product"></td> 
            <td><input class="qty" type="number" min="0" value="1"></td> 
            <td><input class="unit" list="unitOptions" placeholder="bv. kg"></td> 
            <td><input class="weight" type="number" min="0" value="1"></td>
            <td class="totalWeight">0</td>
            <td><input class="price" type="number" min="0" value="0"></td> 
            <td class="rowTotal">R0.00</td> 
            <td class="remove-cell">
                <button class="remove-btn">✖</button>
            </td>
        </tr>
    `;
  calculate();
};

const negativeModal = document.getElementById("negativeModal");
const negativeOk = document.getElementById("negativeOk");
let inputWithNegative = null;
let previousValue = null;

document.addEventListener("focusin", (e) => {
  if (e.target.classList.contains("unit")) {
    e.target.dataset.prevUnit = e.target.value;
    e.target.value = "";
  }
});

document.addEventListener("focusout", (e) => {
  if (e.target.classList.contains("unit") && !e.target.value) {
    e.target.value = e.target.dataset.prevUnit || "";
  }
});

document.addEventListener("focusin", (e) => {
  if (
    e.target.classList.contains("qty") ||
    e.target.classList.contains("price") ||
    e.target.classList.contains("weight")
  ) {
    e.target.dataset.previousValue = e.target.value;
  }
});

document.addEventListener("input", (e) => {
  if (
    e.target.classList.contains("qty") ||
    e.target.classList.contains("price") ||
    e.target.classList.contains("weight")
  ) {
    const value = parseFloat(e.target.value);
    if (value < 0) {
      inputWithNegative = e.target;
      previousValue = e.target.dataset.previousValue;
      e.target.value = previousValue;
      negativeModal.classList.add("show");
      calculate();
    }
  }
});

negativeOk.onclick = () => {
  negativeModal.classList.remove("show");
  inputWithNegative = null;
  previousValue = null;
};

let rowToRemove = null;

const removeModal = document.getElementById("removeModal");
const removeProductInfo = document.getElementById("removeProductInfo");
const confirmRemove = document.getElementById("confirmRemove");
const cancelRemove = document.getElementById("cancelRemove");

document.addEventListener("click", (e) => {
  if (e.target.classList.contains("remove-btn")) {
    rowToRemove = e.target.closest("tr");
    const product =
      rowToRemove.querySelector(".product")?.value || "Naamlose Produk";
    const quantity = rowToRemove.querySelector(".qty")?.value || "0";
    const unit = rowToRemove.querySelector(".unit")?.value || "";
    const weight = rowToRemove.querySelector(".weight")?.value || "0";
    const totalWeight =
      rowToRemove.querySelector(".totalWeight")?.textContent || "0";
    const price = rowToRemove.querySelector(".price")?.value || "0";
    removeProductInfo.innerHTML = ` 
        <p><strong>Produk: </strong> ${product}</p>
        <p><strong>Hoeveelheid: </strong> ${quantity}</p>
        <p><strong>Eenheid: </strong> ${unit}</p>
        <p><strong>Gewig/Volume: </strong> ${weight}</p>
        <p><strong>Totale Gewig/Volume: </strong> ${totalWeight}</p>
        <p><strong>Prys: </strong> R${price}</p>
        `;
    removeModal.classList.add("show");
  }
});

confirmRemove.addEventListener("click", () => {
  if (rowToRemove) {
    rowToRemove.remove();
    rowToRemove = null;
  }
  removeModal.classList.remove("show");
  calculate();
});

cancelRemove.addEventListener("click", () => {
  rowToRemove = null;
  removeModal.classList.remove("show");
});

document.getElementById("downloadList").addEventListener("click", async () => {
  calculate();

  if (!window.jspdf) {
    alert(
      "Jammer, die PDF-aflaaihulpmiddel kon nie laai nie. Herlaai asseblief die bladsy en probeer weer.",
    );
    return;
  }

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF();

  const logoBase64 =
    "data:image/jpeg;base64,";

  try {
    doc.addImage(logoBase64, "JPEG", 165, 10, 30, 15);
  } catch (error) {
    console.warn("Logo could not be loaded:", error);
  }

  const mealID = localStorage.getItem("meal");
  const category = localStorage.getItem("category");

  let mealName = "Pasgemaakte Produklys";

  if (category && mealID && foodData[category]) {
    const meal = foodData[category].meals.find((m) => m.id === mealID);
    if (meal) {
      mealName = meal.name;
    }
  }

  doc.setFontSize(20);
  doc.setTextColor(6, 72, 70);
  doc.text("Produklys", 14, 20);

  doc.setFontSize(13);
  doc.setTextColor(95, 95, 95);
  doc.text(`Ete/Drankie: ${mealName}`, 14, 30);

  const date = new Date().toLocaleDateString("en-ZA");

  doc.setFontSize(10);
  doc.text(`Geskatte Produkkoste - ${date}`, 14, 37);

  const rows = [];

  document.querySelectorAll("#ingredientTable tr").forEach((row) => {
    const product = row.querySelector(".product")?.value || "Naamlose Produk";
    const quantity = parseFloat(row.querySelector(".qty")?.value) || 0;
    const unit = row.querySelector(".unit")?.value || "";
    const weight = parseFloat(row.querySelector(".weight")?.value) || 0;
    const totalWeight =
      parseFloat(row.querySelector(".totalWeight")?.textContent) || "0";
    const price = parseFloat(row.querySelector(".price")?.value) || 0;

    let priceWeight = weight;
    if (unit === "g" || unit === "ml") {
      priceWeight = weight / 1000;
    }
    const rowTotal = quantity * price;

    rows.push([
      product,
      quantity,
      unit,
      weight,
      `${totalWeight} ${unit}`,
      `R${price.toFixed(2)}`,
      `R${rowTotal.toFixed(2)}`,
    ]);
  });

  const totalCapital =
    document.getElementById("capital").textContent || "R0.00";

  doc.autoTable({
    startY: 45,
    head: [
      [
        "Produk",
        "Hoev.",
        "Eenheid",
        "Gew./Vol.",
        "Totale Gew./Vol.",
        "Prys",
        "Geskatte Totaal",
      ],
    ],
    body: rows,
    theme: "grid",
    headStyles: {
      fillColor: [6, 72, 70],
      textColor: [255, 255, 255],
      fontStyle: "bold",
    },
    alternateRowStyles: {
      fillColor: [242, 238, 235],
    },
    styles: {
      fontSize: 9,
      cellPadding: 4,
      textColor: [95, 95, 95],
    },
    columnStyles: {
      0: { cellWidth: 40 },
      1: { cellWidth: 20 },
      2: { cellWidth: 22 },
      3: { cellWidth: 20 },
      4: { cellWidth: 27 },
      5: { cellWidth: 25 },
      6: { cellWidth: 25 },
    },
    margin: {
      left: 14,
      right: 14,
    },
  });

  let finalY = doc.lastAutoTable.finalY + 10;

  const pageHeight = doc.internal.pageSize.getHeight();

  const totalBoxHeight = 25;
  const spaceBetween = 10;

  const disclaimer =
    "Let asseblief daarop dat hierdie bedrag moontlik nie die totale koste verteenwoordig wat jy sal aangaan nie. " +
    "Die werklike koste kan hoër of laer wees, afhangende van verskeie faktore. " +
    "Hierdie syfer word as \'n skatting verskaf om jou \'n aanduiding te gee van die moontlike uitgawes betrokke.";

  const disclaimerLines = doc.splitTextToSize(disclaimer, 180);

  const disclaimerHeight = disclaimerLines.length * 4;

  const footerSpace = 20;

  if (
    finalY + totalBoxHeight + spaceBetween + disclaimerHeight + footerSpace >
    pageHeight
  ) {
    doc.addPage();
    finalY = 20;
  }

  doc.setFillColor(49, 153, 102);
  doc.roundedRect(14, finalY, 186, 25, 4, 4, "F");

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(12);
  doc.setFont(undefined, "bold");

  doc.text("TOTALE AANVANGSKAPITAAL", 20, finalY + 10);

  doc.setFontSize(16);

  doc.text(totalCapital, 20, finalY + 19);

  finalY += 35;

  doc.setTextColor(95, 95, 95);
  doc.setFontSize(8);
  doc.setFont(undefined, "normal");

  doc.text(disclaimerLines, 14, finalY);

  const pageCount = doc.internal.getNumberOfPages();

  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    const pageHeight = doc.internal.pageSize.getHeight();
    const pageWidth = doc.internal.pageSize.getWidth();
    doc.setFontSize(8);
    doc.setTextColor(95, 95, 95);

    doc.text(`Bladsy ${i} van ${pageCount}`, pageWidth - 14, pageHeight - 8, {
      align: "right",
    });
  }

  const safeMealName = mealName.replace(/[^a-z0-9]/gi, "_").toLowerCase();

  doc.save(`${safeMealName}_produklys.pdf`);
});
